/**
 * Component: Free SEO Audit &amp; Analysis Tool
 * Author: @md-mostafa-niloy (https://tailwindflex.com/@md-mostafa-niloy)
 * Source: https://tailwindflex.com/@md-mostafa-niloy/free-seo-audit-analysis-tool
 * Attribution: Créé par @md-mostafa-niloy sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function FreeSeoAuditAnalysisTool() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>Free SEO Analyzer Tool | Visernic</title>

    <meta name="description" content="Analyze your website's SEO with Visernic's free auditing tool. Check 50+ ranking factors including on-page SEO, performance, and security.">
    <meta name="author" content="Visernic Limited">
    <meta property="og:image" content="https://i.postimg.cc/bwR0cd3C/547687027.png">
    <link rel="icon" type="image/png" href="https://i.postimg.cc/26RKc169/icon-1.png">
    <link rel="apple-touch-icon" href="https://i.postimg.cc/26RKc169/icon-1.png">

    <link href="https://fonts.googleapis.com/css2?family=Sora:wght@400;500;600;700&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.2/css/all.min.css">



    <style>
        :root {
            --rm-blue: #069ede; --rm-dark: #2a303b; --rm-text: #7e8299; --rm-heading: #3f4254;
            --rm-bg: #f9f9fc; --rm-border: #ebecf3;
            --success: #1bc5bd; --warning: #ffa800; --danger: #f64e60;
        }
        * { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }
        body {
            font-family: 'Inter', sans-serif; background-color: var(--rm-bg);
            color: var(--rm-text); line-height: 1.6; overflow-x: hidden;
        }
        h1, h2, h3, h4, h5, h6 { font-family: 'Sora', sans-serif; color: var(--rm-heading); font-weight: 600; }
        .container { width: 100%; max-width: 1140px; margin: 0 auto; padding: 0 24px; }
        a { text-decoration: none; color: inherit; }

        /* --- HEADER --- */
        .header { background: #fff; padding: 18px 0; border-bottom: 1px solid var(--rm-border); position: sticky; top: 0; z-index: 100; }
        .nav { display: flex; justify-content: space-between; align-items: center; }
        .logo { font-size: 1.4rem; font-weight: 700; color: var(--rm-dark); display: flex; align-items: center; gap: 10px; }
        .logo img { height: 32px; width: auto; }
        .nav-btn { background: var(--rm-blue); color: #fff; padding: 10px 25px; border-radius: 6px; font-weight: 600; font-size: 0.95rem; transition: 0.2s; }
        .nav-btn:hover { background: #0582b6; transform: translateY(-2px); box-shadow: 0 5px 15px -5px rgba(6, 158, 222, 0.4); }

        /* --- HERO & SEARCH --- */
        .hero { text-align: center; padding: 80px 20px 100px; background: #fff; border-bottom: 1px solid var(--rm-border); }
        .hero h1 { font-size: clamp(2.2rem, 5vw, 3.5rem); margin-bottom: 20px; color: var(--rm-dark); letter-spacing: -1px; }
        .hero p { font-size: 1.2rem; max-width: 650px; margin: 0 auto 40px; }

        .search-box { max-width: 750px; margin: 0 auto; position: relative; z-index: 10; box-shadow: 0 20px 40px rgba(82,63,105,0.1); }
        .input-group {
            display: flex; background: #fff; padding: 8px; border-radius: 10px;
            border: 1px solid var(--rm-border); transition: 0.3s;
        }
        .input-group:focus-within { border-color: var(--rm-blue); box-shadow: 0 0 0 4px rgba(6, 158, 222, 0.1); }
        .rm-input {
            flex: 1; padding: 15px 25px; font-size: 1.1rem; border: none;
            outline: none; color: var(--rm-dark); width: 100%;
        }
        .search-btn-main {
            background: var(--rm-blue); color: #fff; border: none; padding: 0 40px;
            font-size: 1.1rem; font-weight: 700; border-radius: 8px; cursor: pointer;
            transition: 0.2s;
        }
        .search-btn-main:hover { background: #0582b6; }

        /* --- LANDING SECTIONS --- */
        .section { padding: 80px 0; }
        .sec-title { text-align: center; margin-bottom: 50px; font-size: 2.2rem; color: var(--rm-dark); }
        .grid-3 { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 30px; }
        .feature-card {
            background: #fff; padding: 40px 30px; border-radius: 16px;
            box-shadow: 0 2px 6px rgba(82,63,105,.04); border: 1px solid var(--rm-border);
            transition: 0.3s;
        }
        .feature-card:hover { transform: translateY(-10px); box-shadow: 0 20px 40px rgba(82,63,105,0.1); }
        .f-icon { font-size: 2.5rem; color: var(--rm-blue); margin-bottom: 25px; }
        .feature-card h3 { margin-bottom: 15px; font-size: 1.4rem; }

        .faq-grid { display: grid; gap: 20px; max-width: 850px; margin: 0 auto; }
        .faq-item { background: #fff; padding: 30px; border-radius: 14px; border: 1px solid var(--rm-border); }
        .faq-item h4 { color: var(--rm-blue); margin-bottom: 12px; font-size: 1.2rem; display: flex; align-items: center; gap: 10px; }

        /* --- DASHBOARD --- */
        #dashboard { display: none; padding: 50px 0 100px; }

        /* Scorecard (Perfect Mobile Stack) */
        .score-overview {
            background: #fff; border-radius: 16px; padding: 40px;
            box-shadow: 0 2px 6px rgba(82,63,105,.04); margin-bottom: 40px;
            display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 40px;
        }
        .score-left { display: flex; align-items: center; gap: 40px; flex: 2; min-width: 300px; }
        .rm-gauge { width: 160px; height: 160px; position: relative; flex-shrink: 0; }
        .rm-gauge svg { width: 100%; height: 100%; transform: rotate(-90deg); }
        .rm-gauge circle { fill: none; stroke-width: 10; }
        .gauge-bg { stroke: var(--rm-border); }
        .gauge-val {
            stroke: var(--danger); stroke-linecap: round;
            stroke-dasharray: 440; stroke-dashoffset: 440; transition: 1.5s ease;
        }
        .score-text {
            position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
            text-align: center; line-height: 0.9;
        }
        .score-text h2 { font-size: 3.5rem; color: var(--rm-dark); margin: 0; }
        .score-text span { font-size: 0.85rem; font-weight: 700; text-transform: uppercase; color: var(--rm-text); }

        .url-badge {
            background: var(--rm-bg); padding: 6px 16px; border-radius: 50px; font-size: 0.9rem;
            display: inline-block; margin-bottom: 15px; max-width: 100%;
            overflow: hidden; text-overflow: ellipsis; white-space: nowrap; border: 1px solid var(--rm-border);
        }

        .score-stats { display: flex; gap: 40px; flex: 1; justify-content: flex-end; }
        .stat-val { font-size: 2.2rem; font-weight: 700; line-height: 1; margin-bottom: 8px; }
        .stat-label { font-size: 0.8rem; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; }

        /* Reports */
        .rm-section {
            background: #fff; border-radius: 16px; overflow: hidden;
            box-shadow: 0 2px 6px rgba(82,63,105,.04); margin-bottom: 35px; border: 1px solid var(--rm-border);
        }
        .rm-sec-header {
            padding: 25px 40px; border-bottom: 1px solid var(--rm-border); background: #fff;
            display: flex; align-items: center; gap: 15px; font-size: 1.3rem;
        }
        .rm-sec-icon { color: var(--rm-blue); }

        .rm-audit {
            padding: 30px 40px; border-bottom: 1px solid var(--rm-border);
            display: flex; gap: 25px; align-items: flex-start;
        }
        .rm-audit:last-child { border-bottom: none; }
        .audit-status { font-size: 1.6rem; flex-shrink: 0; margin-top: 2px; }
        .audit-content { flex: 1; min-width: 0; }
        .audit-content h4 { font-size: 1.15rem; margin-bottom: 10px; color: var(--rm-dark); }
        .audit-desc { font-size: 1rem; margin-bottom: 12px; line-height: 1.6; }
        .audit-data {
            background: #f8f9fb; border: 1px dashed #d1d5db; padding: 8px 15px;
            border-radius: 8px; font-family: monospace; font-size: 0.9rem;
            display: inline-block; max-width: 100%; overflow-x: auto; color: var(--rm-heading);
        }

        /* Search Preview */
        .preview-box {
            background: #fff; padding: 18px; border: 1px solid var(--rm-border); border-radius: 10px;
            font-family: arial, sans-serif; max-width: 600px; box-shadow: 0 2px 5px rgba(0,0,0,0.05);
        }
        .prev-title { color: #1a0dab; font-size: 20px; line-height: 1.3; margin-bottom: 4px; }
        .prev-url { color: #006621; font-size: 14px; margin-bottom: 4px; }
        .prev-desc { color: #545454; font-size: 14px; line-height: 1.4; }

        /* UTILS */
        .text-success { color: var(--success); } .text-warning { color: var(--warning); } .text-danger { color: var(--danger); }
        #loader { display: none; padding: 100px 20px; text-align: center; }
        .rm-spinner {
            width: 60px; height: 60px; border: 5px solid var(--rm-border); border-top-color: var(--rm-blue);
            border-radius: 50%; animation: spin 1s infinite linear; margin: 0 auto 30px;
        }
        @keyframes spin { to { transform: rotate(360deg); } }
        #error { display: none; padding: 20px; background: #fee2e2; color: #c53030; border-radius: 12px; text-align: center; margin: 30px auto; max-width: 700px; font-weight: 600; }

        /* --- MOBILE RESPONSIVE FIXES --- */
        @media (max-width: 992px) {
            .score-overview { flex-direction: column; text-align: center; padding: 30px 20px; }
            .score-left { flex-direction: column; width: 100%; gap: 25px; }
            .score-stats { justify-content: center; width: 100%; gap: 30px; }
            .rm-audit { flex-direction: column; gap: 15px; padding: 25px 20px; }
            .rm-sec-header { padding: 20px; }
            .hero h1 { font-size: 2.5rem; }
            .input-group { flex-direction: column; padding: 8px; }
            .rm-input { text-align: center; margin-bottom: 10px; border-bottom: 1px solid var(--rm-border); }
            .search-btn-main { width: 100%; padding: 15px 0; }
        }
    </style>
</head>
<body>

    <header class="header">
        <div class="container nav">
            <div class="logo">
                <img src="https://i.postimg.cc/26RKc169/icon-1.png" alt="Visernic Logo">
                Visernic SEO
            </div>
            <a href="#analyze" class="nav-btn">Analyze Now</a>
        </div>
    </header>

    <div class="hero" id="analyze">
        <div class="container">
            <h1>Free SEO Audit & Analysis Tool</h1>
            <p>Instant SEO analysis of your website. Check 50+ ranking factors including on-page SEO, technical issues, and mobile performance.</p>
            <div class="search-box">
                <form id="sForm" class="input-group">
                    <input type="url" id="urlIn" class="rm-input" placeholder="Enter your website URL..." required autocomplete="off">
                    <button type="submit" class="search-btn-main">START AUDIT</button>
                </form>
            </div>
        </div>
    </div>

    <div class="container">
        <div id="error"></div>
        <div id="loader">
            <div class="rm-spinner"></div>
            <h2 style="color: var(--rm-heading); margin-bottom: 10px;">Scanning Website...</h2>
            <p>Our bots are crawling your pages and checking ranking signals.</p>
        </div>
    </div>

    <div id="landing">
        <section class="section">
            <div class="container">
                <h2 class="sec-title">Why Use Our SEO Tool?</h2>
                <div class="grid-3">
                    <div class="feature-card">
                        <i class="fas fa-bolt f-icon"></i>
                        <h3>Lightning Fast</h3>
                        <p>Get a complete technical SEO report in under 60 seconds. Our triple-core engine crawls faster than ever.</p>
                    </div>
                    <div class="feature-card">
                        <i class="fas fa-list-check f-icon"></i>
                        <h3>50+ Checks</h3>
                        <p>We analyze everything from meta tags and headings to advanced Schema markup and security headers.</p>
                    </div>
                    <div class="feature-card">
                        <i class="fas fa-mobile-screen-button f-icon"></i>
                        <h3>Mobile Ready</h3>
                        <p>Ensure your site meets Google's mobile-first indexing standards with our viewport and responsiveness checks.</p>
                    </div>
                </div>
            </div>
        </section>

        <section class="section" style="background: #fff; border-top: 1px solid var(--rm-border);">
            <div class="container">
                <h2 class="sec-title">Frequently Asked Questions</h2>
                <div class="faq-grid">
                    <div class="faq-item">
                        <h4><i class="fas fa-circle-question"></i> Is this tool 100% free?</h4>
                        <p>Yes, you can run unlimited SEO audits for free. There are no hidden costs or limits.</p>
                    </div>
                    <div class="faq-item">
                        <h4><i class="fas fa-robot"></i> How does it work?</h4>
                        <p>Our bot crawls your provided URL just like Google, analyzing the HTML structure and technical assets.</p>
                    </div>
                    <div class="faq-item">
                        <h4><i class="fas fa-chart-line"></i> How do I fix the errors?</h4>
                        <p>Each failed test comes with a "How to fix" guide. Follow the recommendations to improve your score.</p>
                    </div>
                    <div class="faq-item">
                        <h4><i class="fas fa-shield-halved"></i> Is my data secure?</h4>
                        <p>We do not store any analyzed data. Your reports are generated in real-time and are private to you.</p>
                    </div>
                </div>
            </div>
        </section>
    </div>

    <main id="dashboard">
        <div class="container">
            <div class="score-overview">
                <div class="score-left">
                    <div class="rm-gauge">
                        <svg viewBox="0 0 100 100"><circle class="gauge-bg" cx="50" cy="50" r="45"></circle><circle id="scoreCircle" class="gauge-val" cx="50" cy="50" r="45"></circle></svg>
                        <div class="score-text"><h2 id="finalScore">0</h2><span>/100</span></div>
                    </div>
                    <div>
                        <div class="url-badge" id="analyzedUrl">https://visernic.com</div>
                        <h3 id="verdict" style="font-size: 1.8rem; margin-bottom: 10px;">Analyzing...</h3>
                        <p>SEO Analysis & Overview Report</p>
                    </div>
                </div>
                <div class="score-stats">
                    <div><div class="stat-val text-success" id="pass">0</div><div class="stat-label">Passed</div></div>
                    <div><div class="stat-val text-warning" id="warn">0</div><div class="stat-label">Warnings</div></div>
                    <div><div class="stat-val text-danger" id="fail">0</div><div class="stat-label">Failed</div></div>
                </div>
            </div>

            <div class="rm-section">
                <div class="rm-sec-header"><i class="fas fa-search rm-sec-icon"></i><h2>Basic SEO</h2></div>
                <div id="basic-audits"></div>
            </div>
            <div class="rm-section">
                <div class="rm-sec-header"><i class="fas fa-sliders-h rm-sec-icon"></i><h2>Advanced SEO</h2></div>
                <div id="adv-audits"></div>
            </div>
             <div class="rm-section">
                <div class="rm-sec-header"><i class="fas fa-tachometer-alt rm-sec-icon"></i><h2>Performance</h2></div>
                <div id="perf-audits"></div>
            </div>
             <div class="rm-section">
                <div class="rm-sec-header"><i class="fas fa-lock rm-sec-icon"></i><h2>Security</h2></div>
                <div id="sec-audits"></div>
            </div>
             <div class="rm-section">
                <div class="rm-sec-header"><i class="fas fa-share-nodes rm-sec-icon"></i><h2>Social</h2></div>
                <div id="soc-audits"></div>
            </div>

        </div>
    </main>

    <footer style="text-align: center; padding: 50px 0; border-top: 1px solid var(--rm-border); margin-top: 60px; background: #fff;">
        <div class="container">
            <img src="https://i.postimg.cc/26RKc169/icon-1.png" alt="Visernic" style="height: 40px; margin-bottom: 20px; opacity: 0.8;">
            <p>© 2025 Visernic SEO Tool. Development by <a href="https://visernic.com" target="_blank" style="color: var(--rm-blue); font-weight: 700;">Visernic Limited</a>.</p>
        </div>
    </footer>


</body>
</html>" }} />
  );
}
